// The release job (spec 9): the Marketplace screenshots in VS Code 1.141, generated by scripts/review/release-job.mjs.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { DIRTY_FILE, EXPAND_FILES, EXPANDED, EXPLORER_ROWS, FIXTURE, FOLDERS, OPEN_FILES, RITUAL, SHEET_PAGES, TERMINAL_PROFILE, TERMINAL_PROFILE_NAME, releaseJob } from '../scripts/review/release-job.mjs';

const root = path.resolve(import.meta.dirname, '..');
const read = (file) => fs.readFileSync(path.join(root, file), 'utf8');
const json = (file) => JSON.parse(read(file));
const job = () => json('review/jobs/release.json');
const scene = (name) => job().scenes.find((candidate) => candidate.name === name);
const keyOf = (command) => json('review/profile/keybindings.json').find((binding) => binding.command === command && binding.args === undefined)?.key;

test('review/jobs/release.json is the generator\'s job for this package (node scripts/review/release-job.mjs)', () => {
  assert.deepEqual(job(), releaseJob(json('package.json')));
});

test('the release job opens its fixture in VS Code\'s default window at 100%, in all four themes, no scene picking a theme', () => {
  const { workspace, settings, passes, scenes, commitSheets } = job();
  assert.equal(workspace, FIXTURE);
  assert.deepEqual(settings, { 'window.newWindowDimensions': 'default' });
  assert.deepEqual(passes, [{ name: 'main', vsix: ['spellbound-main.vsix'], scales: [1] }]);
  assert.deepEqual(scenes.map(({ name }) => name), ['showcase', 'icon-sheet', 'icon-sheet-2', 'icon-sheet-3', 'terminal']);
  assert.deepEqual(commitSheets, [], 'the images go to assets/screenshots/, not to a gate folder');
  for (const { name, settings: own = {} } of scenes) {
    for (const key of ['workbench.colorTheme', 'workbench.iconTheme', 'workbench.productIconTheme']) assert.ok(!(key in own), `${name} keeps ${key}`);
  }
});

test('the showcase waits for the whole fixture in the Explorer, three tabs with one unsaved, and the installed 2.0.0 file icons', () => {
  const top = fs.readdirSync(path.join(root, FIXTURE));
  const inside = EXPANDED.flatMap((folder) => fs.readdirSync(path.join(root, FIXTURE, folder)));
  assert.deepEqual([...EXPLORER_ROWS].sort(), [...top, ...inside].sort(), 'every top-level entry and the files of the open folders, once');
  assert.ok(EXPLORER_ROWS.length <= 25, 'the rows fit the default window');
  assert.deepEqual(FOLDERS, top.filter((entry) => fs.statSync(path.join(root, FIXTURE, entry)).isDirectory()).sort());
  for (const file of OPEN_FILES) assert.ok(fs.existsSync(path.join(root, FIXTURE, file)), file);
  const { settings, setup, teardown } = scene('showcase');
  assert.deepEqual(EXPAND_FILES.map((file) => file.split('/')[0]), EXPANDED.filter((folder) => folder !== 'src'), 'a file revealed in each open folder but src');
  // A revealed SVG opens in the text editor: VS Code's image preview is a webview outside .part.editor, so the
  // editor-focus wait after its reveal would never pass.
  for (const file of EXPAND_FILES.filter((entry) => entry.endsWith('.svg'))) assert.equal(settings['workbench.editorAssociations']?.['*.svg'], 'default', file);
  assert.deepEqual(setup.filter((step) => step.insert).map((step) => step.insert), [...EXPAND_FILES, ...OPEN_FILES.slice(0, 2), ' ', OPEN_FILES[2]]);
  assert.equal(setup.filter((step) => step.press === keyOf('workbench.action.closeAllEditors')).length, 1, 'the revealed files are closed before the three tabs open');
  const wait = setup.at(-1).waitFor;
  assert.ok(wait.includes(`rows.length === ${EXPLORER_ROWS.length}`) && wait.includes("tabs.querySelectorAll('.tab.dirty').length === 1"));
  // The icon is drawn from this package's own folder, in whichever of the three file icon sets the first theme uses.
  const icon = new RegExp(JSON.parse(/new RegExp\(("(?:[^"\\]|\\.)*")\)\.test/.exec(wait)[1]));
  const { name, version } = json('package.json');
  for (const set of ['dark', 'light', 'high-contrast']) assert.ok(icon.test(`url("vscode-file://x/.${name}-${version}/icons/file-icons/${set}/gem-cut.svg")`), set);
  assert.ok(!icon.test(`url("vscode-file://x/.${name}-1.9.9/icons/file-icons/dark/gem-cut.svg")`), 'another version');
  // Closing an unsaved editor opens a save dialog: the teardown reverts it first.
  const revert = keyOf('workbench.action.files.revert');
  assert.deepEqual(teardown.filter((step) => step.insert || step.press === revert).map((step) => step.insert ?? 'revert'), [DIRTY_FILE, 'revert']);
  const files = (dir) => fs.readdirSync(path.join(root, dir), { withFileTypes: true }).flatMap((entry) => (entry.isDirectory() ? files(`${dir}/${entry.name}`) : [`${dir}/${entry.name}`]));
  const all = files(FIXTURE);
  assert.ok(all.length >= 16, `${all.length} fixture files`);
  const tracked = spawnSync('git', ['check-ignore', '--no-index', '--stdin'], { cwd: root, input: all.join('\n'), encoding: 'utf8' });
  assert.ifError(tracked.error);
  assert.equal(tracked.status, 1, `git ignores: ${tracked.stdout}${tracked.stderr}`);
  assert.equal(tracked.stdout, '', 'git tracks the whole fixture');
});

test('the icon sheet scenes turn gate 4\'s three pages of 51 drawings, and the last puts the panel back', () => {
  const drawings = Object.keys(json('icons/product-icon-map.json').drawings).length;
  assert.equal(Math.ceil(drawings / 51), SHEET_PAGES, `${drawings} drawings`);
  const pages = job().scenes.filter(({ name }) => name.startsWith('icon-sheet'));
  pages.forEach(({ setup }, index) => assert.ok(setup.some((step) => String(step.waitFor).includes(`'page ${index + 1} of ${SHEET_PAGES}'`)), `page ${index + 1}`));
  assert.deepEqual(pages.at(-1).teardown.map((step) => step.press), [keyOf('spellboundReview.iconSheetPage'), keyOf('workbench.action.toggleMaximizedPanel'), keyOf('workbench.action.closePanel')]);
});

test('the terminal runs only the ritual, with no prompt: witchyterm\'s ll without the owner column, then the 16 colours', () => {
  const { settings, setup } = scene('terminal');
  assert.deepEqual(settings['terminal.integrated.profiles.windows'], { [TERMINAL_PROFILE_NAME]: TERMINAL_PROFILE });
  assert.equal(settings['terminal.integrated.defaultProfile.windows'], TERMINAL_PROFILE_NAME);
  assert.equal(settings['terminal.integrated.minimumContrastRatio'], 1, 'the README setting for an exact match');
  assert.deepEqual(TERMINAL_PROFILE, { path: 'C:\\Windows\\System32\\wsl.exe', args: ['-e', 'fish', '-i', '-c', 'source scripts/ritual.fish'] });
  assert.ok(setup.some((step) => step.press === keyOf('workbench.action.terminal.new')), 'opens the default profile');
  // The panel is maximized before the terminal starts: a resize after the ritual has printed makes ConPTY repaint only
  // the rows the small panel showed, and ll's listing is left in the scrollback, off the capture.
  const presses = setup.map((step) => step.press);
  assert.ok(presses.indexOf(keyOf('workbench.action.toggleMaximizedPanel')) !== -1, 'maximizes the panel');
  assert.ok(presses.indexOf(keyOf('workbench.action.toggleMaximizedPanel')) < presses.indexOf(keyOf('workbench.action.terminal.new')), 'maximized before the terminal starts');
  // ...and opened on the icon sheet: a panel opened on its Terminal view starts a terminal of its own, a second one.
  assert.ok(presses.indexOf(keyOf('spellboundReview.iconSheet.focus')) !== -1, 'opens the panel on the icon sheet');
  assert.ok(presses.indexOf(keyOf('spellboundReview.iconSheet.focus')) < presses.indexOf(keyOf('workbench.action.toggleMaximizedPanel')), 'the panel is open before it is maximized');
  const commands = read(path.join(FIXTURE, RITUAL)).split('\n').map((line) => line.trim()).filter((line) => line && !line.startsWith('#'));
  assert.deepEqual(commands, [
    'll --no-user',
    'echo',
    'set -l names black red green yellow blue magenta cyan white',
    'for i in (seq 0 7)',
    'set -l name $names[(math $i + 1)]',
    "printf '\\e[3%sm%-8s\\e[0m \\e[4%sm      \\e[0m \\e[10%sm      \\e[0m \\e[9%smbright %s\\e[0m\\n' $i $name $i $i $i $name",
    'end',
    'sleep 3600',
  ]);
});

test('the Windows Terminal capture closes only the window it opened, by handle, also one that appears after the 30 s wait', () => {
  // Final review M16: a window that appeared after the deadline was never closed. The title is checked to be free before
  // the launch, so a window with that title found afterwards is this script's; it is closed by its handle (WM_CLOSE).
  const script = read('scripts/review/windows-terminal.ps1');
  assert.doesNotMatch(script, /Stop-Process|taskkill|Get-Process/i, 'never by process name or image');
  assert.equal([...script.matchAll(/PostMessage\(/g)].length, 2, 'the declaration and the one close');
  assert.match(script, /if \(\$window -ne \[IntPtr\]::Zero\) \{ \[SpellboundWin\]::PostMessage\(\$window, 0x10, \[IntPtr\]::Zero, \[IntPtr\]::Zero\)/);
  const late = script.indexOf('if ($window -eq [IntPtr]::Zero) {', script.indexOf('$deadline = (Get-Date).AddSeconds(30)'));
  const timeout = script.indexOf("throw \"no Windows Terminal window titled '$title' within 30 s", late);
  assert.ok(late > 0 && timeout > late, 'the timeout path looks again before it throws');
  const grace = script.slice(late, timeout);
  assert.match(grace, /\$window = \[SpellboundWin\]::FindWindow\(\$class, \$title\)/, 'by the same class and title');
  assert.ok(script.indexOf('} finally {') > timeout, 'so the finally block closes a late window too');
});
